#!/usr/bin/env node
/* Targeted check: Siegfried/SWISSIMAGE overlays + their records (maps-0 data). */
import { spawn } from 'node:child_process';
import { rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const PORT = 9334;
const BASE = process.argv[2] || 'http://127.0.0.1:8787';
const userDataDir = path.join(os.tmpdir(), `kz-ovl-${process.pid}`);
const chrome = spawn('chromium', [
  '--headless=new', `--remote-debugging-port=${PORT}`,
  '--no-first-run', '--no-default-browser-check', '--disable-gpu', '--no-sandbox',
  '--window-size=1440,950', `--user-data-dir=${userDataDir}`, 'about:blank',
], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

class CDP {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); }
  static async connect(url) {
    const ws = new WebSocket(url);
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
    const cdp = new CDP(ws);
    ws.onmessage = (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id) {
        const p = cdp.pending.get(msg.id);
        if (p) { cdp.pending.delete(msg.id); msg.error ? p.rej(new Error(JSON.stringify(msg.error))) : p.res(msg.result); }
      }
    };
    return cdp;
  }
  send(method, params = {}) {
    const id = ++this.id;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((res, rej) => this.pending.set(id, { res, rej }));
  }
  async eval(expr) {
    const r = await this.send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.text + ' ' + (r.exceptionDetails.exception?.description || ''));
    return r.result.value;
  }
}

let failures = 0;
const check = (name, ok, detail = '') => { console.log(`${ok ? '✔' : '✖'} ${name}${detail ? ` — ${detail}` : ''}`); if (!ok) failures++; };

try {
  let wsUrl;
  for (let i = 0; i < 60 && !wsUrl; i++) {
    try { wsUrl = (await (await fetch(`http://127.0.0.1:${PORT}/json/version`)).json()).webSocketDebuggerUrl; } catch { await sleep(250); }
  }
  const target = await (await fetch(`http://127.0.0.1:${PORT}/json/new?${encodeURIComponent(`${BASE}/?from=1860&to=1910`)}`, { method: 'PUT' })).json();
  const cdp = await CDP.connect(target.webSocketDebuggerUrl);
  await cdp.send('Runtime.enable');
  await sleep(3000);

  const options = await cdp.eval(`(() => {
    const sel = document.querySelector('#overlay-select');
    return [...sel.options].map((o) => ({ value: o.value, text: o.text }));
  })()`);
  check('overlay picker offers the Siegfried and SWISSIMAGE layers', options.some((o) => o.value === 'ch.swisstopo.hiks-siegfried') && options.some((o) => o.value === 'ch.swisstopo.swissimage-product_1946'), JSON.stringify(options.filter((o) => /hiks|swissimage/.test(o.value)).map((o) => o.value)));

  const rows = await cdp.eval(`(() => {
    const list = [...document.querySelectorAll('#result-list > *')];
    return { total: list.length, siegfried: list.filter((n) => /Siegfriedkarte/.test(n.textContent)).length, text: list.slice(0, 2).map((n) => n.textContent.trim().slice(0, 60)) };
  })()`);
  check('year range 1860–1910 lists the Siegfriedkarte records', rows.siegfried >= 3, JSON.stringify(rows));

  // Select the Siegfried layer and move the edition slider to 1900.
  const edition = await cdp.eval(`(() => {
    const sel = document.querySelector('#overlay-select');
    sel.value = 'ch.swisstopo.hiks-siegfried';
    sel.dispatchEvent(new Event('change', { bubbles: true }));
    const time = document.querySelector('#overlay-time');
    return { hidden: time?.closest('[hidden]') !== null, max: time?.max, current: document.querySelector('#overlay-time-output')?.textContent };
  })()`);
  check('Siegfried layer exposes its 80 editions', edition.max === '79', JSON.stringify(edition));

  const url = await cdp.eval(`(() => {
    const values = [...document.querySelectorAll('#overlay-time')].length ? null : null;
    const slider = document.querySelector('#overlay-time');
    const target = 30; // ascending values: index 30 -> 1900 (1870 + 30)
    slider.value = String(target);
    slider.dispatchEvent(new Event('input', { bubbles: true }));
    return { value: slider.value, out: document.querySelector('#overlay-time-output')?.textContent, search: location.search };
  })()`);
  await sleep(2500);
  const tiles = await cdp.eval(`(() => {
    const imgs = [...document.querySelectorAll('.map-layer--overlay img')];
    return { count: imgs.length, src: imgs.map((i) => i.src).filter((s) => /hiks-siegfried/.test(s)).slice(0, 2), loaded: imgs.filter((i) => i.complete && i.naturalWidth > 0).length };
  })()`);
  check('Siegfried 1900 tiles load in the map overlay', tiles.count > 0 && tiles.loaded > 0 && tiles.src.length > 0, JSON.stringify({ ...url, ...tiles }));

  // Open a Siegfried record from the list and check the detail view.
  const detail = await cdp.eval(`(async () => {
    const row = [...document.querySelectorAll('#result-list > *')].find((n) => /Siegfriedkarte/.test(n.textContent));
    const button = row?.querySelector('button, a') || row;
    button.click();
    await new Promise((r) => setTimeout(r, 1500));
    const panel = document.querySelector('#detail');
    const img = panel?.querySelector('img');
    const link = panel?.querySelector('a[href*="map.geo.admin.ch"]');
    return { hidden: panel?.hidden, text: panel?.textContent.replace(/\\s+/g, ' ').slice(0, 260), img: img ? { src: img.src, w: img.naturalWidth, state: img.dataset.state } : null, link: link?.href };
  })()`);
  check('Siegfried record detail shows the swisstopo preview and original-record link', detail.hidden === false && detail.link?.includes('map.geo.admin.ch') && detail.img != null, JSON.stringify(detail));

  await rm(userDataDir, { recursive: true, force: true }).catch(() => {});
} catch (err) {
  check('overlay check completed without throwing', false, err.message);
} finally {
  chrome.kill('SIGKILL');
  console.log(failures === 0 ? 'ALL OK' : `${failures} FAILED`);
  process.exit(failures === 0 ? 0 : 1);
}

