#!/usr/bin/env node
/* Probe: does the IIIF viewer pan with arrow keys? */
import { spawn } from 'node:child_process';
import { rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const PORT = 9335;
const BASE = process.argv[2] || 'http://127.0.0.1:8787';
const userDataDir = path.join(os.tmpdir(), `kz-pan-${process.pid}`);
const chrome = spawn('chromium', ['--headless=new', `--remote-debugging-port=${PORT}`, '--no-first-run', '--no-default-browser-check', '--disable-gpu', '--no-sandbox', '--window-size=1440,950', `--user-data-dir=${userDataDir}`, 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

class CDP {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); this.events = []; }
  static async connect(url) {
    const ws = new WebSocket(url);
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
    const cdp = new CDP(ws);
    ws.onmessage = (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id) { const p = cdp.pending.get(msg.id); if (p) { cdp.pending.delete(msg.id); msg.error ? p.rej(new Error(JSON.stringify(msg.error))) : p.res(msg.result); } }
      else cdp.events.push(msg);
    };
    return cdp;
  }
  send(method, params = {}) { const id = ++this.id; this.ws.send(JSON.stringify({ id, method, params })); return new Promise((res, rej) => this.pending.set(id, { res, rej })); }
  async eval(expr) { const r = await this.send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.text); return r.result.value; }
  press(key, code, keyCode) { return this.send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode: keyCode }).then(() => this.send('Input.dispatchKeyEvent', { type: 'keyUp', key, code, windowsVirtualKeyCode: keyCode })); }
}

try {
  let wsUrl;
  for (let i = 0; i < 60 && !wsUrl; i++) { try { wsUrl = (await (await fetch(`http://127.0.0.1:${PORT}/json/version`)).json()).webSocketDebuggerUrl; } catch { await sleep(250); } }
  const target = await (await fetch(`http://127.0.0.1:${PORT}/json/new?${encodeURIComponent(`${BASE}/?sel=e-rara%3A6507640`)}`, { method: 'PUT' })).json();
  const cdp = await CDP.connect(target.webSocketDebuggerUrl);
  await cdp.send('Runtime.enable');
  await sleep(3500);
  console.log('viewer present', await cdp.eval(`Boolean(document.querySelector('.app-viewer__image'))`));
  await cdp.eval(`document.querySelector('#viewer-zoom-in').click(); document.querySelector('#viewer-zoom-in').click(); true`);
  await sleep(2500);
  const before = await cdp.eval(`(() => ({ src: document.querySelector('.app-viewer__image')?.src, focus: (document.querySelector('#viewer-stage').focus(), document.activeElement?.id), tabindex: document.querySelector('#viewer-stage')?.getAttribute('tabindex'), rect: document.querySelector('#viewer-stage')?.getBoundingClientRect().toJSON() }))()`);
  console.log('before', JSON.stringify(before));
  await cdp.press('ArrowRight', 'ArrowRight', 39);
  await cdp.press('ArrowRight', 'ArrowRight', 39);
  await sleep(2200);
  const after = await cdp.eval(`(() => ({ src: document.querySelector('.app-viewer__image')?.src, focus: document.activeElement?.id, readout: document.querySelector('#viewer-resolution')?.textContent }))()`);
  console.log('after', JSON.stringify(after));
  console.log('changed', before.src !== after.src);

  // Try dispatching a synthetic KeyboardEvent directly on the stage.
  await cdp.eval(`(() => { const s = document.querySelector('#viewer-stage'); s.focus(); s.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true })); return document.activeElement?.id; })()`);
  await sleep(2200);
  const after2 = await cdp.eval(`document.querySelector('.app-viewer__image')?.src`);
  console.log('after synthetic', JSON.stringify(after2), 'changed', after.src !== after2);
  await rm(userDataDir, { recursive: true, force: true }).catch(() => {});
} catch (err) {
  console.error('failed', err);
} finally {
  chrome.kill('SIGKILL');
  process.exit(0);
}

