import path from 'node:path';

const PORT = 9336;
const BASE = process.argv[2] || 'http://127.0.0.1:8787';
const userDataDir = path.join(os.tmpdir(), `kz-coll-${process.pid}`);
const chrome = spawn('chromium', ['--headless=new', `--remote-debugging-port=${PORT}`, '--no-first-run', '--no-default-browser-check', '--disable-gpu', '--no-sandbox', '--window-size=1440,950', `--user-data-dir=${userDataDir}`, 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

class CDP {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); this.errors = []; }
  static async connect(url) {
    const ws = new WebSocket(url);
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
    const cdp = new CDP(ws);
    ws.onmessage = (ev) => { const m = JSON.parse(ev.data); if (m.id) { const p = cdp.pending.get(m.id); if (p) { cdp.pending.delete(m.id); m.error ? p.rej(new Error(JSON.stringify(m.error))) : p.res(m.result); } } else if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') cdp.errors.push(m.params.args.map((a) => a.value ?? a.description).join(' ')); };
    return cdp;
  }
  send(method, params = {}) { const id = ++this.id; this.ws.send(JSON.stringify({ id, method, params })); return new Promise((res, rej) => this.pending.set(id, { res, rej })); }
  async eval(expr) { const r = await this.send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.text); return r.result.value; }
}

let failures = 0;
const check = (name, ok, detail = '') => { console.log(`${ok ? '✔' : '✖'} ${name}${detail ? ` — ${detail}` : ''}`); if (!ok) failures++; };

try {
  let wsUrl;
  for (let i = 0; i < 60 && !wsUrl; i++) { try { wsUrl = (await (await fetch(`http://127.0.0.1:${PORT}/json/version`)).json()).webSocketDebuggerUrl; } catch { await sleep(250); } }
  const target = await (await fetch(`http://127.0.0.1:${PORT}/json/new?${encodeURIComponent(`${BASE}/?from=1850&to=1950`)}`, { method: 'PUT' })).json();
  const cdp = await CDP.connect(target.webSocketDebuggerUrl);
  await cdp.send('Runtime.enable');
  await sleep(3000);

  const options = await cdp.eval(`[...document.querySelectorAll('#collection-filter option')].map((o) => o.value)`);
  check('collection select lists the documented series', options.length >= 6 && options.includes('Siegfriedkarte 1:25 000'), JSON.stringify(options));

  const filtered = await cdp.eval(`(async () => {
    const sel = document.querySelector('#collection-filter');
    sel.value = 'Siegfriedkarte 1:25 000';
    sel.dispatchEvent(new Event('change', { bubbles: true }));
    await new Promise((r) => setTimeout(r, 800));
    const rows = [...document.querySelectorAll('#result-list > *')];
    return { search: location.search, rows: rows.length, allSiegfried: rows.every((n) => /Siegfriedkarte/.test(n.textContent)), count: document.querySelector('#result-count')?.textContent };
  })()`);
  check('choosing a collection filters the result list and writes ?c=', filtered.rows === 9 && filtered.allSiegfried && /(^|&)c=Siegfriedkarte/.test(decodeURIComponent(filtered.search)), JSON.stringify(filtered));

  await cdp.send('Page.navigate', { url: `${BASE}/?from=1850&to=1950&c=${encodeURIComponent('Siegfriedkarte 1:25 000')}` });
  await sleep(2500);
  const restored = await cdp.eval(`(() => ({ value: document.querySelector('#collection-filter')?.value, rows: document.querySelectorAll('#result-list > *').length }))()`);
  check('shared ?c= URL restores the collection filter', restored.value === 'Siegfriedkarte 1:25 000' && restored.rows === 9, JSON.stringify(restored));

  const reset = await cdp.eval(`(async () => {
    document.querySelector('#reset-filters').click();
    await new Promise((r) => setTimeout(r, 700));
    return { value: document.querySelector('#collection-filter')?.value, search: location.search, rows: document.querySelectorAll('#result-list > *').length };
  })()`);
  check('reset clears the collection filter', reset.value === '' && !/c=/.test(reset.search) && reset.rows > 9, JSON.stringify(reset));

  check('no console errors during the collection filter run', cdp.errors.length === 0, cdp.errors.slice(0, 2).join(' | '));
  await rm(userDataDir, { recursive: true, force: true }).catch(() => {});
} catch (err) {
  check('collection check completed without throwing', false, err.message);
} finally {
  chrome.kill('SIGKILL');
  console.log(failures === 0 ? 'ALL OK' : `${failures} FAILED`);
  process.exit(failures === 0 ? 0 : 1);
}

